    'mining_barge',
    'exhumer',
    'jump_freighter',
    'industrial_command',
    'hauler',
    'freighter',
    'industrial_base',

    // --- Fighters ---
    'light_fighter',
    'heavy_fighter',

    // --- Structures ---
    'control_tower',
    'starbase_structure',
    'sentry_gun',
    'orbital_infrastructure',

    // --- Deployables ---
    'mobile_cyno',
    'mobile_warp_disruptor',
    'mobile_tractor_unit',
    'mobile_observatory'
]);

// --- FILTER FUNCTION ---
function filterKill(kill) {
    // 1. Alliance Filter (Multi-ID Support)
    if (allianceIds.size > 0) {
        const victimAllianceId = String(kill.victim?.alliance_id || '0');
        const attackerAllianceIds = new Set(kill.attackers.map(a => String(a.alliance_id || '0')));

        const victimMatch = allianceIds.has(victimAllianceId);
        const attackerMatch = [...attackerAllianceIds].some(id => allianceIds.has(id));

        if (!victimMatch && !attackerMatch) return false;
    }

    // 2. Main Filters
    if (filtersMain.size > 0) {
        if (filtersMain.has('solo') && !kill.is_solo) {
            return false;
        }

        if (filtersMain.has('npc')) {
            const finalBlow = kill.attackers.find(a => a.final_blow);
            if (!finalBlow || !finalBlow.is_npc) {
                return false;
            }
        }

        // Hide Pods
        if (filtersMain.has('hide-pods') && (kill.victim_ship_class === 'capsule')) {
            return false;
        }

        // Hide Structures
        if (filtersMain.has('hide-structures')) {
            const basic = kill.victim_ship_class || '';
            const detailed = kill.victim_ship_class_detailed || '';

            if (['structure', 'pos'].includes(basic)) {
                return false;
            }
            if (['control_tower', 'starbase_structure', 'sentry_gun', 'deployable', 'mobile_cyno', 'customs_office', 'fighter', 'orbital_infrastructure'].includes(detailed)) {
                return false;
            }
        }

        // Hide Trash
        if (filtersMain.has('hide-trash') && ['rookie_ship', 'shuttle'].includes(kill.victim_ship_class)) {
            return false;
        }
    }

    // 3. Space Filters
    if (filtersSpace.size > 0) {
        const spaceType = kill.space_type || 'unknown';
        let matchesSpace = false;

        if (filtersSpace.has('hs') && spaceType === 'highsec') {
            matchesSpace = true;
        }
        if (filtersSpace.has('ls') && spaceType === 'lowsec') {
            matchesSpace = true;
        }
        if (filtersSpace.has('ns') && spaceType === 'nullsec') {
            matchesSpace = true;
        }
        if (filtersSpace.has('wh') && spaceType === 'wormhole') {
            matchesSpace = true;
        }
        if (filtersSpace.has('ab') && spaceType === 'abyssal') {
            matchesSpace = true;
        }

        if (!matchesSpace) {
            return false;
        }
    }

    // 4. ISK Filters
    if (filtersIsk.size > 0) {
        const value = Number(kill.total_value) || 0;
        let matchesIsk = false;

        if (filtersIsk.has('sub10m') && value < 10000000) {
            matchesIsk = true;
        }
        if (filtersIsk.has('10m-100m') && value >= 10000000 && value < 100000000) {
            matchesIsk = true;
        }
        if (filtersIsk.has('100m-1b') && value >= 100000000 && value < 1000000000) {
            matchesIsk = true;
        }
        if (filtersIsk.has('1b-10b') && value >= 1000000000 && value < 10000000000) {
            matchesIsk = true;
        }
        if (filtersIsk.has('10b-20b') && value >= 10000000000 && value < 20000000000) {
            matchesIsk = true;
        }
        if (filtersIsk.has('20b-50b') && value >= 20000000000 && value < 50000000000) {
            matchesIsk = true;
        }
        if (filtersIsk.has('50b') && value >= 50000000000) {
            matchesIsk = true;
        }

        if (!matchesIsk) {
            return false;
        }
    }

    // 5. Ship Filters (Dual-Layer Support)
    if (filtersShip.size > 0) {
        const basic = kill.victim_ship_class;
        const detailed = kill.victim_ship_class_detailed;

        const matchBasic = basic && filtersShip.has(basic);
        const matchDetailed = detailed && filtersShip.has(detailed);

        if (!matchBasic && !matchDetailed) {
            return false;
        }
    }

    // 6. Search Logic
    if (searchQuery.length > 0) {
        const searchTerms = searchQuery.toLowerCase().split(' ').filter(t => t.length > 0);

        const fields = [
            kill.killmail_id,
            kill.solar_system_name,
            kill.victim?.character_name,
            kill.victim?.corporation_name,
            kill.victim?.alliance_name,
            kill.victim?.ship_type_name,
            kill.victim_ship_class,
            kill.victim_ship_class_detailed
        ];

        (kill.attackers || []).forEach(a => {
            fields.push(
                a.character_name,
                a.corporation_name,
                a.alliance_name,
                a.ship_type_name
            );
        });

        const searchableText = fields.filter(Boolean).join(' ').toLowerCase();

        return searchTerms.every(term => searchableText.includes(term));
    }

    return true;
}

// --- MAIN EXECUTION ---
return (async () => {
    try {
        // ---------------------------------------------------------
        // 1. INTELLIGENT INDEX SELECTION
        // ---------------------------------------------------------
        let sourceKeys = [];

        // STRATEGY: Union keys from the MOST SPECIFIC filter category active.
        // Priority: Alliance > Ship > NPC > ISK > Space > All
        // We do NOT union across categories (e.g. Alliance + Ship) because Redis intersection is expensive/complex here.
        // Instead, we pick the category that likely has the smallest dataset and filter the rest in memory.

        if (allianceIds.size > 0) {
            allianceIds.forEach(id => {
                sourceKeys.push(`intel:followed:alliance:${id}`);
            });
        }
        else if (filtersShip.size > 0) {
            // Ship filters are usually very specific, so they take priority over NPC/ISK/Space
            for (const selectedClass of filtersShip) {
                if (DETAILED_CLASSES_SET.has(selectedClass)) {
                    sourceKeys.push(`intel:losses:ship_class_detailed:${selectedClass}`);
                } else {
                    sourceKeys.push(`intel:losses:ship_class:${selectedClass}`);
                }
            }
        }
        else if (filtersMain.has('npc')) {
            sourceKeys = [KEY_KILLS_NPC];
        }
        else if (filtersIsk.size > 0) {
             const iskIndexMap = {
                'sub10m': 'intel:kills:isk:sub10m',
                '10m-100m': 'intel:kills:isk:10m-100m',
                '100m-1b': 'intel:kills:isk:100m-1b',
                '1b-10b': 'intel:kills:isk:1b-10b',
                '10b-20b': 'intel:kills:isk:10b-20b',
                '20b-50b': 'intel:kills:isk:20b-50b',
                '50b': 'intel:kills:isk:50b'
            };
            filtersIsk.forEach(f => { 
                if (iskIndexMap[f]) {
                    sourceKeys.push(iskIndexMap[f]);
                }
            });
            // If ISK filters are present but map failed (shouldn't happen), fallback to ALL
            if (sourceKeys.length === 0) sourceKeys = [KEY_KILLS_ALL];
        }
        else if (filtersSpace.size > 0) {
             const spaceMap = {
                'hs': 'highsec',
                'ls': 'lowsec',
                'ns': 'nullsec',
                'wh': 'wormhole',
                'ab': 'abyssal'
             };
             // Union all selected space keys
             filtersSpace.forEach(s => {
                 if (spaceMap[s]) {
                     sourceKeys.push(`intel:kills:space:${spaceMap[s]}`);
                 }
             });
             if (sourceKeys.length === 0) sourceKeys = [KEY_KILLS_ALL];
        }
        else {
            sourceKeys = [KEY_KILLS_ALL];
        }

        // ---------------------------------------------------------
        // 2. FETCH KILL IDS (Optimized & Union)
        // ---------------------------------------------------------
        let rawIds = [];

        // SCENARIO A: LIVE UPDATE (No Loop)
        if (latestKnownId) {
            const allResults = [];
            for (const sourceKey of sourceKeys) {
                const latestTime = await redis.zscore(sourceKey, latestKnownId);
                if (latestTime) {
                    const ids = await redis.zrangebyscore(sourceKey, `(${latestTime}`, '+inf', 'WITHSCORES');
                    for (let i = 0; i < ids.length; i += 2) {
                        allResults.push({ id: ids[i], timestamp: parseFloat(ids[i + 1]) });
                    }
                }
            }
            const uniqueMap = new Map();
            allResults.forEach(item => { if (!uniqueMap.has(item.id)) uniqueMap.set(item.id, item); });
            const uniqueResults = Array.from(uniqueMap.values()).sort((a, b) => b.timestamp - a.timestamp);
            rawIds = uniqueResults.map(i => i.id);

            // Fetch Data Immediately
            if (rawIds.length > 0) {
                const pipeline = redis.pipeline();
                rawIds.forEach(id => pipeline.hget(KEY_KILL_DATA, id));
                const rawData = await pipeline.exec();
                const fetchedKills = rawData
                    .filter(([err]) => !err)
                    .map(([, json]) => { try { return json ? JSON.parse(json) : null; } catch (e) { return null; } })
                    .filter(Boolean);
                finalKills = fetchedKills.filter(filterKill);
                finalKills.sort((a, b) => new Date(b.killmail_time) - new Date(a.killmail_time));
            }
        }
        // SCENARIO B: INITIAL / BACKFILL (Deep Search Loop)
        else {
            let iterations = 0;
            let currentCursor = beforeKillId;

            while (iterations < DEEP_SEARCH_LIMIT && finalKills.length < FETCH_LIMIT) {
                let batchResults = [];

                // Progressive Batch Sizing (Stage 1-4 Strategy)
                let currentBatchSize = 500; // Stage 2 (Standard)

                // If requesting a large batch (Deep Search), start aggressive immediately
                if (FETCH_LIMIT >= 500) {
                    currentBatchSize = 10000; // Stage 4 (Sweeper) - Immediate Max Power
                } else {
                    if (iterations >= 5) currentBatchSize = 2000;  // Stage 3 (Ramp up)
                    if (iterations >= 10) currentBatchSize = 10000; // Stage 4 (Sweeper)
                }

                // Fetch Batch of IDs from all sources
                for (const sourceKey of sourceKeys) {
                    let indexIds = [];
                    if (currentCursor) {
                        const oldestTime = await redis.zscore(sourceKey, currentCursor);
                        if (oldestTime) {
                            indexIds = await redis.zrevrangebyscore(sourceKey, `(${oldestTime}`, '-inf', 'WITHSCORES', 'LIMIT', 0, currentBatchSize);
                        }
                    } else {
                        indexIds = await redis.zrevrange(sourceKey, 0, currentBatchSize, 'WITHSCORES');
                    }

                    for (let i = 0; i < indexIds.length; i += 2) {
                        batchResults.push({ id: indexIds[i], timestamp: parseFloat(indexIds[i + 1]) });
                    }
                }

                if (batchResults.length === 0) break; // End of DB

                // Sort & Dedupe Batch
                const uniqueMap = new Map();
                batchResults.forEach(item => { if (!uniqueMap.has(item.id)) uniqueMap.set(item.id, item); });
                const sortedBatch = Array.from(uniqueMap.values()).sort((a, b) => b.timestamp - a.timestamp);

                // Update Cursor for next loop (use the oldest from this batch)
                currentCursor = sortedBatch[sortedBatch.length - 1].id;

                // Fetch Data for Batch
                const pipeline = redis.pipeline();
                sortedBatch.forEach(item => pipeline.hget(KEY_KILL_DATA, item.id));
                const rawData = await pipeline.exec();

                const fetchedKills = rawData
                    .filter(([err]) => !err)
                    .map(([, json]) => { try { return json ? JSON.parse(json) : null; } catch (e) { return null; } })
                    .filter(Boolean);

                // Filter Batch
                const validKills = fetchedKills.filter(filterKill);

                // Add to Final List
                finalKills.push(...validKills);

                iterations++;
            }

            // Final Sort & Slice
            finalKills.sort((a, b) => new Date(b.killmail_time) - new Date(a.killmail_time));
            if (finalKills.length > FETCH_LIMIT) {
                finalKills = finalKills.slice(0, FETCH_LIMIT);
            }
        }

        // Set pagination cursor
        if (finalKills.length > 0) {
            oldest_kill_id_for_client = finalKills[finalKills.length - 1].killmail_id;
        } else if (rawIds.length > 0) {
            // Fallback if we fetched IDs but filtered them all out (and loop finished)
            oldest_kill_id_for_client = rawIds[rawIds.length - 1];
        }

        // ---------------------------------------------------------
        // 4. LOAD GLOBAL CACHED STATS
        // ---------------------------------------------------------
        const [cachedStatsResult, cachedTrendsResult] = await redis.pipeline()
            .get(KEY_CACHED_STATS)
            .get(KEY_CACHED_TRENDS)
            .exec();

        const cachedStatsJson = cachedStatsResult[1];
        const cachedTrendsJson = cachedTrendsResult[1];

        if (cachedStatsJson) {
            try {
                const cs = JSON.parse(cachedStatsJson);
                stats_24h = cs.stats_24h || { kills: 0, isk: 0 };
                total_count = cs.total_count || 0;
                latest_db_killmail_time = cs.latest_db_killmail_time || null;
            } catch (e) {
                // Ignore corrupt stats
            }
        }

        trends = cachedTrendsJson 
            ? JSON.parse(cachedTrendsJson) 
            : { kills: 'stable', isk: 'stable', avgValue: 'stable', total30d: 'stable' };

        // ---------------------------------------------------------
        // 5. GLOBAL 30-DAY STATS (Explicit & Unpacked)
        // ---------------------------------------------------------
        const statsPipeline = redis.pipeline();
        const thirtyDaysAgo = Math.floor(Date.now() / 1000) - (STATS_WINDOW_DAYS * 24 * 60 * 60);

        // Queue: Total Count (Index 0)
        statsPipeline.zcount(KEY_KILLS_ALL, thirtyDaysAgo, '+inf');

        // Queue: ISK Buckets (Indices 1-7)
        statsPipeline.zcount('intel:kills:isk:sub10m', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:isk:10m-100m', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:isk:100m-1b', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:isk:1b-10b', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:isk:10b-20b', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:isk:20b-50b', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:isk:50b', thirtyDaysAgo, '+inf');

        // Queue: Hourly Activity (Indices 8-31) - Fully Unpacked
        statsPipeline.zcount('intel:kills:hour:0', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:1', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:2', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:3', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:4', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:5', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:6', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:7', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:8', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:9', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:10', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:11', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:12', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:13', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:14', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:15', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:16', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:17', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:18', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:19', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:20', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:21', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:22', thirtyDaysAgo, '+inf');
        statsPipeline.zcount('intel:kills:hour:23', thirtyDaysAgo, '+inf');

        const statsResults = await statsPipeline.exec();
        const total30d = statsResults[0][1] || 1; // Avoid divide by zero

        // Process ISK Distribution
        isk_distribution = {
            'sub10m':   { count: statsResults[1][1], percent: parseFloat(((statsResults[1][1] / total30d) * 100).toFixed(1)) },
            '10m-100m': { count: statsResults[2][1], percent: parseFloat(((statsResults[2][1] / total30d) * 100).toFixed(1)) },
            '100m-1b':  { count: statsResults[3][1], percent: parseFloat(((statsResults[3][1] / total30d) * 100).toFixed(1)) },
            '1b-10b':   { count: statsResults[4][1], percent: parseFloat(((statsResults[4][1] / total30d) * 100).toFixed(1)) },
            '10b-20b':  { count: statsResults[5][1], percent: parseFloat(((statsResults[5][1] / total30d) * 100).toFixed(1)) },
            '20b-50b':  { count: statsResults[6][1], percent: parseFloat(((statsResults[6][1] / total30d) * 100).toFixed(1)) },
            '50b':      { count: statsResults[7][1], percent: parseFloat(((statsResults[7][1] / total30d) * 100).toFixed(1)) }
        };

        // Process Heatmap
        // Offset is 8 (1 total + 7 isk buckets)
        activity_heatmap = {};
        for (let h = 0; h < 24; h++) {
            const val = statsResults[h + 8][1] || 0;
            activity_heatmap[h] = { 
                count: val, 
                percent: parseFloat(((val / total30d) * 100).toFixed(1)) 
            };
        }

        // ---------------------------------------------------------
        // 6. MULTI-ALLIANCE STATS AGGREGATION
        // ---------------------------------------------------------
        if (allianceIds && allianceIds.size > 0) {
            const summaryPipeline = redis.pipeline();

            // Queue up all fetch requests
            const idsList = Array.from(allianceIds);
            idsList.forEach(id => {
                summaryPipeline.hgetall(`alliance:summary:${id}`);
            });

            const summaryResults = await summaryPipeline.exec();
            const extraKillIds = new Set();

            // Process results
            if (summaryResults) summaryResults.forEach((res, index) => {
                if (!res[0]) { // No error
                    const summary = res[1];
                    if (summary && Object.keys(summary).length > 0) {
                         const currentId = idsList[index];

                         // Sanitize and Normalize
                         allianceStatsDict[currentId] = {
                            kills: Number(summary.kills) || 0,
                            losses: Number(summary.losses) || 0,
                            // Support legacy naming (value_destroyed vs isk_destroyed)
                            isk_destroyed: Number(summary.iskDestroyed) || Number(summary.value_destroyed) || 0,
                            isk_lost: Number(summary.iskLost) || Number(summary.value_lost) || 0,
                            efficiency: Number(summary.efficiency) || 0,
                            ratio: Number(summary.ratio) || 0,
                            activePilots: Number(summary.activePilots) || 0,
                            lastSeen: Number(summary.lastSeen) || 0,
                            topShip: summary.top_ship || summary.topShip || '-',
                            maxKillId: summary.maxKillId,
                            maxLossId: summary.maxLossId
                         };

                         if (summary.maxKillId) extraKillIds.add(summary.maxKillId);
                         if (summary.maxLossId) extraKillIds.add(summary.maxLossId);
                    }
                }
            });

            // Fetch full kill objects for the max kills/losses
            if (extraKillIds.size > 0) {
                const kmPipeline = redis.pipeline();
                extraKillIds.forEach(id => kmPipeline.hget(KEY_KILL_DATA, id));
                const kmResults = await kmPipeline.exec();

                const kmMap = {};
                kmResults.forEach((res) => {
                    if (!res[0] && res[1]) {
                        try { const k = JSON.parse(res[1]); kmMap[k.killmail_id] = k; } catch(e){}
                    }
                });

                // Attach full objects to stats
                Object.values(allianceStatsDict).forEach(stat => {
                    if (stat.maxKillId) stat.maxKill = kmMap[stat.maxKillId];
                    if (stat.maxLossId) stat.maxLoss = kmMap[stat.maxLossId];
                });
            }

            // Backward compatibility for single selection
            if (allianceIds.size === 1 && Object.keys(allianceStatsDict).length > 0) {
                allianceSummary = Object.values(allianceStatsDict)[0];
            }
        }

    } catch (e) {
        return [{ json: { error: e.message, details: e.stack } }];
    } finally {
        if (redis) redis.quit();
    }

    return [{
        json: {
            kills: finalKills,
            total_count: total_count,
            stats_24h: stats_24h,
            trends: trends,
            isk_distribution: isk_distribution,
            activity_heatmap: activity_heatmap,
            alliance_stats: allianceStatsDict, // DICTIONARY return
            alliance_summary: allianceSummary, // LEGACY return
            oldest_kill_id: oldest_kill_id_for_client,
            latest_db_killmail_time: latest_db_killmail_time
        }
    }];
})();
